import numpy as np
import pandas as pd
from pandas.arrays import SparseArray

_desc1 = "values = np.array([1,2,3], dtype='i8').astype('M8[s]') (also m8, units s/ms/us); fill_value = pd.Timestamp(values[1]).as_unit('ns') (pd.Timedelta for m8); arr = SparseArray(values, fill_value=fill_value); np.asarray(arr, dtype='i8')"

_desc2 = "data = np.array([1,3,5], dtype='M8[s]') (also 'm8[s]'); SparseArray(data).take(np.array([0,-1]), allow_fill=True, fill_value='1970-01-02' for M8, '1 days' for m8)"


def _carry_out_desc1():
    out = []
    for kind in ("M8", "m8"):
        for unit in ("s", "ms", "us"):
            values = np.array([1, 2, 3], dtype="i8").astype(kind + "[" + unit + "]")
            if kind == "M8":
                fill_value = pd.Timestamp(values[1]).as_unit("ns")
            else:
                fill_value = pd.Timedelta(values[1]).as_unit("ns")
            arr = SparseArray(values, fill_value=fill_value)
            out.append(np.asarray(arr, dtype="i8").tolist())
    return out


def _carry_out_desc2():
    out = []
    for kind, fill_value in (("M8", "1970-01-02"), ("m8", "1 days")):
        data = np.array([1, 3, 5], dtype=kind + "[s]")
        taken = SparseArray(data).take(
            np.array([0, -1]), allow_fill=True, fill_value=fill_value
        )
        out.append(np.asarray(taken, dtype="i8").tolist())
    return out


try:
    _r1 = _carry_out_desc1()
except Exception as _e1:
    probe_exception(_desc1, _e1)
else:
    probe(_desc1, _r1)

try:
    _r2 = _carry_out_desc2()
except Exception as _e2:
    probe_exception(_desc2, _e2)
else:
    probe(_desc2, _r2)

